// src/components/App.jsx

import React from 'react';
import TonalitySelector from './TonalitySelector'; // Импорт исправлен ранее
import ChordSelector from './ChordSelector';
import SettingsPanel from './SettingsPanel';
import OutputDisplay from './OutputDisplay';
import useChordGenerator from '../hooks/useChordGenerator';
import { keyPairs } from '../data/vocabulary';

function App() {
  const {
    state,
    sequence,
    sequenceLength,
    forbidVtoIV,
    handleInput,
  } = useChordGenerator();

  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <h1 className="text-3xl font-bold mb-8 text-center">
        ?? Генератор аккордов ?? <br />
        <span className="text-gray-400">by Dm.Isanin</span>
      </h1>
      
      {/* Проверяем, что последовательность существует перед рендером */}
      {sequence && sequence.length > 0 ? (
  // --- ИНТЕРФЕЙС С РЕЗУЛЬТАТОМ ---
  <div className="grid md:grid-cols-2 gap-8">
    {/* Левая колонка */}
    <div>
      <TonalitySelector keyPairs={keyPairs} onSelect={handleInput} />
      <div className="mt-8">
        <h2 className="text-xl font-semibold mb-4">Настройки</h2>
        <SettingsPanel onChange={handleInput} />
      </div>
    </div>
    
    {/* Правая колонка */}
    <div>
      <div className="mb-8">
        <h2 className="text-xl font-semibold mb-4">Ваша последовательность</h2>
        <OutputDisplay sequence={sequence} />
      </div>
      
      <div className="mt-8 space-y-3">
        <button 
          onClick={() => handleInput('generate')} 
          disabled={state !== 'askRepeat'}
          className={`w-full py-3 px-4 rounded-lg ${
            state === 'askRepeat' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-gray-500'
          } text-white font-bold`}
        >
          Сгенерировать снова ({sequenceLength})
        </button>
        
        <button
          onClick={() => handleInput('reset')}
          className="w-full bg-gray-700 hover:bg-gray-600 text-white font-bold py-3 px-4 rounded-lg"
        >
          Начать заново / Выбрать тональность
        </button>
        
        <button
          onClick={() => handleInput('00')}
          className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-4 rounded-lg"
        >
          Быстрая генерация (рандом)
        </button>
      </div>
    </div>
  </div>

) : (
  // --- СТАРТОВЫЙ ЭКРАН И ИНТЕРФЕЙС НАСТРОЙКИ ---
  <>
    {/* Приветственный экран (показываем, если еще ничего не сгенерировано) */}
    <div className="space-y-4 text-center p-8 bg-gray-800 rounded-md mx-auto max-w-2xl mt-10">
      <h1 className="text-4xl md:text-5xl font-bold flex items-center justify-center">
        🎸 Генератор аккордов 🎹
      </h1>
      <p className="text-gray-400 text-lg text-center mb-8">by Dm.Isanin</p>

      <button
        onClick={() => handleInput('00')}
        className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-4 rounded-lg"
      >
        ⚡️ Быстрая генерация
      </button>
    </div>

    {/* Интерфейс пошаговой настройки (показываем, если мы находимся в процессе выбора) */}
    {(state === 'chooseKeyNum' || state === 'chooseKeyType') && (
      <div className="max-w-lg mx-auto mt-10 p-6 bg-gray-800 rounded-md shadow-lg">
        <TonalitySelector keyPairs={keyPairs} onSelect={handleInput} />
      </div>
    )}

    {state === 'chooseChords' && (
      <div className="max-w-lg mx-auto mt-10 p-6 bg-gray-800 rounded-md shadow-lg">
        <h2 className="text-xl font-semibold mb-4">Выберите аккорды для генерации.</h2>
        <form id="chord-selection-form">
          <div id="chord-checkboxes">
            {allChords[key].map((c, i) => (
              <label key={i} className="chord-checkbox block mb-2">
                <input type="checkbox" name="chord" value={`${i + 1}`} defaultChecked /> {i + 1}. {c}
              </label>
            ))}
          </div>
          <div className="mt-4 flex justify-end space-x-3">
            <button type="submit" className="ready-btn bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded">
              Готово
            </button>
          </div>
        </form>
      </div>
    )}
  </>
)} : (
        // Если последовательности нет, показываем стартовое сообщение
<>
          <p className="text-center text-lg mt-10">
            Нажмите кнопку "Быстрая генерация" или пройдите шаги настройки!
          </p>
          
          {/* --- НОВАЯ КНОПКА --- */}
          <button
            onClick={() => handleInput('00')}
            className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-4 rounded-lg mt-8"
          >
            Быстрая генерация (рандом)
          </button>
        </>
      )}
    </div>
  );
}

export default App;
